"""AQS-COM-002 startup sequence, cold start from empty (X-COM-02, A-M-201). Durations are computed from the graph: ZnBr2 first charge
from kWh / charge_kW; heat-ladder warm-up from battery vol x rho x cp x (t_nom - 20 C) over the warm-up source; CO2 condenser pull-down
from an assumed cold mass (A-M-201) over the condenser chiller and EXPANDER backup; H2 bank fill from tube water volume x H2 density at
the bank pressure over the electrolyser H2 rate. Process systems follow AQS-COM-001 order at 25/50/100 %.
Run after _commissioning.py: python3 docs-authority/_startup.py"""
import json, os, sys, math, csv
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(R); sys.path.insert(0, R)
from flow_graph.param.refs import cite
for k in ('NFPA2_2026', 'NFPA855_2026', 'NIST_WEBBOOK', 'PERRY9', 'API521_2020', 'NFPA25_2026'): cite(k)
g = json.load(open('flow_graph/plant_flow_graph.json')); N = {n['unit_id']: n for n in g['nodes']}; P = lambda u: (N.get(u) or {}).get('params') or {}
z = P('ZNBR2'); kwh = float(z.get('kWh') or 0); ck = float(z.get('charge_kW') or 1); t_bat = kwh*0.8/ck
FL = {'thermal oil': (850, 2.2), 'water': (1000, 4.18)}           # PERRY9 typical properties
lad = []
for u in sorted(N):
    p = P(u)
    if N[u].get('class') == 'heat_battery': r, cp = FL.get(p.get('fluid'), (1000, 4.18)); lad.append((u, p['tier'], p['vol_m3'], p['t_nom_C'], p['vol_m3']*r*cp*(p['t_nom_C']-20)/3600))
geo = float((N.get('GEO_HP') or {}).get('continuous_kw', {}).get('value') or 2.0)
q4 = sum(x[4] for x in lad if x[1] == 'Q4'); t_q4 = q4/(2*geo)     # two GEO_HP units, one per ladder (X-RED-07)
ASU = P('CRYO_ASU').get('design') or {}; chill = ASU.get('co2_chill_kW') or 0.03; exb = (ASU.get('expander_backup') or {}).get('cold_kW') or 0
M_COND, CP_SS = 20.0, 0.5                                           # A-M-201: condenser + vessel cold mass, kg 316L; cp kJ/kg K
t_cd = M_COND*CP_SS*(25+20)/(chill*3600); t_cd_b = M_COND*CP_SS*45/(exb*3600) if exb else float('nan')
H = P('CRYO_H2').get('design') or {}; Vb = H.get('tubes', 0)*math.pi/4*(H.get('ID_mm', 0)/1000)**2*H.get('tube_m', 0)
rho_h2 = 14.9                                                       # kg/m3 H2 at 200 bar, 25 C (NIST_WEBBOOK)
mh2 = Vb*rho_h2; h2r = sum(e['rate']['value']*(e.get('composition') or {}).get('H2', 0) for e in g['edges'] if e['from_unit_id'] == 'H2O_ELYZ' and e['presence'] == 'present') or 1
t_h2 = mh2/h2r
seq = list(csv.DictReader(open('docs-authority/inventory/COMMISSIONING.csv'))); systems = list(dict.fromkeys(r['system'] for r in seq))
S = [('0', 'Prerequisites', 'AQS-COM-001 phases 1-3 complete for every system; gas detection (AQS-SAF-006) and fire protection (AQS-SAF-005) in service; fire dead-storage of the water tower full (AQS-BLD-014) before any flammable inventory is admitted (NFPA 25).', '-'),
 ('1', 'Power', f'PV and inverter on; ZnBr2 first charge to 80 % of {kwh:.0f} kWh at {ck:.1f} kW with the purge and H2 detection live (NFPA 855); backup generator run test on load.', f'{t_bat:.1f} h'),
 ('2', 'Water', 'Fill the water tower live store and the process water loop; start UPW polish and recirculate to spec.', 'set by the site supply rate (site data)'),
 ('3', 'Heat ladder', f'Ladder A then B. Q4 batteries ({q4:.1f} kWh total) warmed by GEO_HP, one unit per ladder ({geo:.1f} kW each); Q1-Q3 batteries charge from their own process sources as those start (step 6), diode rule held (no uphill valve). Batteries: ' + '; '.join(f'{u} {t} {e:.1f} kWh' for u, t, v, T, e in lad) + '.', f'{t_q4:.1f} h (Q4)'),
 ('4', 'Inerting and H2/O2', f'N2 purge of the H2 and O2 systems to < 1 % O2 (H2) and < 1 % fuel (O2) (NFPA 2); electrolyser to 25 %, 50 %, 100 %; fill the H2 bank ({Vb:.2f} m3 water volume, {mh2:.1f} kg at 200 bar) at {h2r:.2f} kg/d H2.', f'{t_h2:.1f} d'),
 ('5', 'Gas separation and cold', f'CO2 TSA beds regenerated once at 204 C before first adsorption; CO2 condenser pulled down 25 C to -20 C ({M_COND:.0f} kg cold mass, A-M-201) by the chiller ({chill*1000:.0f} W)' + (f'; with the EXPANDER backup alone ({exb*1000:.0f} W) {t_cd_b:.1f} h' if exb else '') + '. No cryogenic column (CRYO_ASU is TSA and condensing only).', f'{t_cd:.1f} h'),
 ('6', 'Process systems', 'In AQS-COM-001 order: ' + ', '.join(s for s in systems if s not in ('ELEC', 'PUMPED_HYDRO', 'WTR', 'HEAT', 'GAS', 'CRYO')) + '. Each at 25 %, 50 %, 100 % of the graph rate, 24 h per step, hold point on product and vent analysis.', '3 d per system, overlapping'),
 ('7', 'Hydro and fuel cell', 'Hydro set run on a tower draw-down test; fuel cell run on bank H2 to prove the backup path (X-RED).', '1 d')]
md = ['# Startup sequence (cold start from empty)', '', 'Document number: AQS-COM-002', 'Revision: A', 'Date: 2026-10-16', 'Authority: AQS-PLAN-007 X-COM-02. Generated by `docs-authority/_startup.py`. Study. A-M-201.', '',
      '| Step | Stage | Actions | Duration |', '|---|---|---|---|'] + [f'| {a} | {b} | {c} | {d} |' for a, b, c, d in S]
md += ['', 'Shutdown to safe state from any step: process feeds off, H2/O2 isolated at the bank ESD valves (AQS-CTL-003), batteries hold heat, ZnBr2 to standby.']
open('docs-authority/STARTUP.md', 'w').write('\n'.join(md) + '\n'); print(t_bat, q4, t_q4, t_cd, t_cd_b, mh2, t_h2)
